  SOURCE_EXAMPLE,
  contractFetch,
  fakeFetch,
  jsonResponse,
  TARGET_ENDPOINTS,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = { stripeSecretKey: 'sk_test_123', fetch }
    const result = await handle(SOURCE_EXAMPLE as unknown as HubSpotContactPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.stripeCustomerId).toBe('cus_NffrFeUfNV2Hib')
  })
})

describe('handle', () => {
  it('creates a Stripe customer with email and combined name on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.stripe.com/v1/customers' && req.method === 'POST'
        ? jsonResponse({ id: 'cus_test123', object: 'customer', email: 'jane.doe@example.com', name: 'Jane Doe' }, 200)
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: HubSpotContactPayload = {
      properties: {
        email: 'jane.doe@example.com',
        firstname: 'Jane',
        lastname: 'Doe',
        customer_status: true,
      },
    }

    const result = await handle(payload, { stripeSecretKey: 'sk_test_123', fetch })

    expect(result.stripeCustomerId).toBe('cus_test123')
    expect(calls).toHaveLength(1)
    expect(calls[0].method).toBe('POST')
    expect(calls[0].url).toBe('https://api.stripe.com/v1/customers')
    expect(calls[0].headers.get('authorization')).toBe('Bearer sk_test_123')
    expect(calls[0].json).toEqual({ email: 'jane.doe@example.com', name: 'Jane Doe' })
  })

  it('uses email as name when firstname and lastname are missing', async () => {
    const { fetch, calls } = fakeFetch((req) =>
      req.url === 'https://api.stripe.com/v1/customers' && req.method === 'POST'
        ? jsonResponse({ id: 'cus_test456', object: 'customer', email: 'john@example.com', name: 'john@example.com' }, 200)
        : jsonResponse({ error: 'not found' }, 404)
    )

    const payload: HubSpotContactPayload = {
      properties: {
        email: 'john@example.com',
        customer_status: true,
      },
    }

    const result = await handle(payload, { stripeSecretKey: 'sk_test_123', fetch })

    expect(result.stripeCustomerId).toBe('cus_test456')
    expect(calls[0].json).toEqual({ email: 'john@example.com', name: 'john@example.com' })
  })

  it('throws when email is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    const payload = {
      properties: {
        firstname: 'Jane',
        lastname: 'Doe',
        customer_status: true,
      },
    } as HubSpotContactPayload

    await expect(handle(payload, { stripeSecretKey: 'sk_test_123', fetch })).rejects.toThrow(
      'Missing required field: email'
    )
  })

  it('throws when customer_status is missing or not boolean', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    const payload = {
      properties: {
        email: 'jane.doe@example.com',
        firstname: 'Jane',
        lastname: 'Doe',
      },
    } as HubSpotContactPayload

    await expect(handle(payload, { stripeSecretKey: 'sk_test_123', fetch })).rejects.toThrow(
      'Missing required field: customer_status (boolean)'
    )
  })

  it('throws when customer_status is false', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200))

    const payload: HubSpotContactPayload = {
      properties: {
        email: 'jane.doe@example.com',
        firstname: 'Jane',
        lastname: 'Doe',
        customer_status: false,
      },
    }

    await expect(handle(payload, { stripeSecretKey: 'sk_test_123', fetch })).rejects.toThrow(
      'Contact is not marked as a customer (customer_status is false)'
    )
  })

  it('throws on non-2xx response from Stripe with status and endpoint', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Invalid API Key' }, 401))

    const payload: HubSpotContactPayload = {
      properties: {
        email: 'jane.doe@example.com',
        firstname: 'Jane',
        lastname: 'Doe',
        customer_status: true,
      },
    }

    await expect(handle(payload, { stripeSecretKey: 'sk_test_123', fetch })).rejects.toThrow(
      'Stripe API error: 401 Unauthorized for POST https://api.stripe.com/v1/customers'
    )
    expect(calls).toHaveLength(1)
  })

  it('throws on 500 response from Stripe', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({ error: 'Internal server error' }, 500))

    const payload: HubSpotContactPayload = {
      properties: {
        email: 'jane.doe@example.com',
        firstname: 'Jane',
        lastname: 'Doe',
        customer_status: true,
      },
    }

    await expect(handle(payload, { stripeSecretKey: 'sk_test_123', fetch })).rejects.toThrow(
      'Stripe API error: 500 Internal Server Error for POST https://api.stripe.com/v1/customers'
    )
  })
})

